  "settings.magicPrompts.page.group.planImprove.title": "Melhoria de plano",
  "settings.magicPrompts.page.group.planImprove.description": "Prompt oculto usado ao enviar um plano salvo para um fluxo de melhoria.",
  "settings.magicPrompts.page.group.planTodo.title": "Planejamento de tarefas",
  "settings.magicPrompts.page.group.planTodo.description": "Prompt oculto usado ao enviar uma tarefa para uma nova sessão de planejamento.",
  "settings.magicPrompts.page.group.planImplement.title": "Implementação de plano",
  "settings.magicPrompts.page.group.planImplement.description": "Prompt oculto usado ao enviar um plano salvo para um fluxo de implementação.",
  "settings.magicPrompts.page.group.sessionSummary.title": "Resumo de sessão",
  "settings.magicPrompts.page.group.sessionSummary.description": "Prompts usados pelo comando /summary: mensagem visível do usuário + instruções ocultas. Não destrutivo: não compacta o histórico da sessão.",
  "settings.magicPrompts.page.group.sessionWorkspaceReview.title": "Revisão do workspace",
  "settings.magicPrompts.page.group.sessionExplore.title": "Tour do código",
  "settings.magicPrompts.page.group.sessionExplore.description": "Prompts usados pelo comando /explore: mensagem visível do usuário + instruções ocultas. Investiga o repositório e dá uma orientação estruturada — o panorama geral, os módulos principais, como se conectam e por onde começar — em vez de uma listagem arquivo por arquivo.",
  "settings.magicPrompts.page.group.sessionWorkspaceReview.description": "Prompts usados pelo comando /workspace-review: mensagem visível do usuário + instruções ocultas. Revisa o diff do workspace: se ele alcança sua intenção e se está correto e adequado, classificando os achados por severidade.",
  "settings.magicPrompts.page.group.sessionFeaturePlan.title": "Planejamento de funcionalidade",
  "settings.magicPrompts.page.group.sessionFeaturePlan.description": "Prompts usados pelo comando /plan-feature: mensagem visível do usuário + instruções ocultas. Executa um diálogo guiado que investiga o código e faz perguntas de esclarecimento em pequenos lotes antes de produzir um plano de implementação.",
  "settings.magicPrompts.page.group.sessionCatchUp.title": "Retomada de contexto",
  "settings.magicPrompts.page.group.sessionCatchUp.description": "Prompts usados pelo comando /catch-up: mensagem visível do usuário + instruções ocultas. Constrói um contexto ciente da branch — os commits da branch, seu PR e o trabalho não confirmado juntos — para entender o que você estava fazendo, e então dá um resumo fácil de assimilar e um próximo passo focado no produto.",
  "settings.magicPrompts.page.group.sessionDebug.title": "Depuração",
  "settings.magicPrompts.page.group.sessionDebug.description": "Prompts usados pelo comando /debug: mensagem visível do usuário + instruções ocultas. Executa uma investigação guiada da causa raiz: captura o sintoma, formula hipóteses, verifica-as no código e confirma a causa antes de propor uma correção.",
  "settings.magicPrompts.page.group.sessionWeigh.title": "Comparar abordagens",
  "settings.magicPrompts.page.group.sessionWeigh.description": "Prompts usados pelo comando /weigh: mensagem visível do usuário + instruções ocultas. Investiga o código e então apresenta 2-3 abordagens distintas com seus prós e contras e uma recomendação, sem escrever um plano ou código.",
  "settings.magicPrompts.page.group.sessionFusion.title": "Fusion",
  "settings.magicPrompts.page.group.sessionFusion.description": "Prompts usados para combinar saídas de multi-run em uma resposta final: mensagem visível do usuário + instruções ocultas antes dos resultados de origem.",
